guide.simple_bytestorage_scripting.examp:
§eЗабирати зі скрині§r
§bvar c = side("up");
function tick() { if (c) c.pull(); }§r

§eГодувати групу печей§r
(шини з ID "smelters", печі з їхнього північного боку)
§bfunction tick() {
  var f = side("north", "smelters");
  if (f) f.push("minecraft:raw_iron", 16);
}§r

§eЗбирати з усіх скринь "inbox"§r
§bfunction tick() {
  var i = side("up", "inbox");
  if (i) i.pull();
}§r

§eДві групи§r
§bfunction tick() {
  var a = side("up", "in"), b = side("up", "out");
  if (a && b) a.move(b);
}§r

§eАвтокрафт за браку§r
§bfunction tick() {
  if (net.count("minecraft:stick") < 64)
    net.craft("minecraft:stick", 64);
}§r
